#include <stdlib.h>

int main(void) {
    int N, M, C;
    if (scanf("%d %d %d", &N, &M, &C) != 3) return 0;

    int *next = calloc((size_t)M + 1, sizeof(int));
    char *visited = calloc((size_t)M + 1, sizeof(char));

    for (int i = 0; i < N; i++) {
        int A, D;
        scanf("%d %d", &A, &D);
        if (next[D] == 0) next[D] = A;
    }

    int swaps = 0;
    int song = C;

    while (1) {
        if (visited[song]) {
            printf("-1\n");
            break;
        }

        visited[song] = 1;

        if (next[song] == 0) {
            printf("%d\n", swaps);
            break;
        }

        song = next[song];
        swaps++;
    }

    free(next);
    free(visited);
    return 0;
